{
  "application": "ppt-generation",
  "case_id": "case-tiobe-index",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 6,
    "audience": "Software engineering leads and technology strategists planning language adoption",
    "tone": "data-forward, analytical, professional"
  },
  "brief": {
    "title": "TIOBE Index March 2026: Programming Language Popularity Rankings and Trends",
    "one_liner": "Python leads at 21.25% but posts the largest year-over-year decline among the top 5, while C surges to second and Go drops from 7th to 16th.",
    "goal": "Give technology decision-makers a clear, data-backed view of which programming languages are rising, falling, and holding steady so they can align hiring, training, and tooling investments with industry momentum."
  },
  "slides": [
    {
      "id": "title",
      "title": "TIOBE Index March 2026: How 20+ Search Engines Rank the World's Programming Languages",
      "objective": "Introduce the TIOBE index methodology and scope. Establish that ratings are based on search-engine hit counts across Google, Bing, Wikipedia, Amazon, and 20+ other sites."
    },
    {
      "id": "top-20",
      "title": "Python Holds #1 at 21.25% but C Surges to #2 with the Largest Gain",
      "objective": "Present the full top-20 ranking table with March 2026 position, prior-year position, rating percentage, and year-over-year change. Highlight Python's dominance and C's +2.02% rise."
    },
    {
      "id": "movers",
      "title": "Perl Jumps 13 Spots, R Climbs 7, and Go Drops 9 -- The Biggest Rank Shifts of 2026",
      "objective": "Focus on the most dramatic movers: Perl (24th to 11th), R (16th to 9th), Swift (26th to 20th) rising; Go (7th to 16th), C++ (2nd to 3rd), Java (3rd to 4th) falling. Use a visual to contrast gainers and losers."
    },
    {
      "id": "historical",
      "title": "From Lisp at #2 in 1986 to Python at #1 in 2026: How Language Rankings Shifted Over Time",
      "objective": "Present the long-term ranking table with snapshots from 1986 to 2026 and the historical trend chart covering 2002–2026. Show how Python rose from unranked to dominant, how Java peaked and declined, and how C has remained in the top 2 across all nine measurement points spanning four decades."
    },
    {
      "id": "hall-of-fame",
      "title": "Python Wins Language of the Year 6 Times -- More Than Any Other Language",
      "objective": "Display the Hall of Fame winners from 2016 to 2025 and note Python's six total wins (2007, 2010, 2018, 2020, 2021, 2024). Highlight that C# won twice recently (2023, 2025) and that Go's 2016 win preceded its current decline. Note that the 2017 winner is not available in the source data."
    },
    {
      "id": "takeaways",
      "title": "The Top 4 Languages Hold 49% of the Index: What This Means for Your Tech Stack",
      "objective": "Summarize key findings and actionable implications: Python's dominance vs. its decline trajectory, C's resurgence, the legacy-language revival (Perl, Fortran, R), Go's sharp fall, and the concentration risk of betting on only a few languages."
    }
  ]
}

