    <link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;700;800;900&family=DM+Sans:ital,wght@0,400;0,500;0,600;1,400&display=swap" rel="stylesheet">
    <style>
        /* === THEME VARIABLES === */
        :root {
            --bg-primary: #0c1222;
            --bg-secondary: #131b2e;
            --bg-card: #182038;
            --bg-card-alt: #1c2640;
            --text-primary: #e8ecf4;
            --text-secondary: #8b95ad;
            --text-muted: #5a6580;
            --accent-teal: #2dd4bf;
            --accent-teal-dim: rgba(45, 212, 191, 0.15);
            --accent-amber: #f59e0b;
            --accent-amber-dim: rgba(245, 158, 11, 0.12);
            --accent-red: #f87171;
            --accent-red-dim: rgba(248, 113, 113, 0.12);
            --accent-green: #34d399;
            --accent-green-dim: rgba(52, 211, 153, 0.12);
            --accent-blue: #60a5fa;
            --accent-blue-dim: rgba(96, 165, 250, 0.12);
            --border: rgba(255,255,255,0.06);
            --border-accent: rgba(45, 212, 191, 0.25);

            --font-display: 'Archivo', sans-serif;
            --font-body: 'DM Sans', sans-serif;

            --title-size: clamp(1.6rem, 3.2vw, 2.8rem);
            --h2-size: clamp(1.2rem, 2.5vw, 2rem);
            --h3-size: clamp(0.95rem, 1.8vw, 1.35rem);
            --body-size: clamp(0.7rem, 1.15vw, 0.95rem);
            --small-size: clamp(0.6rem, 0.9vw, 0.8rem);
            --tiny-size: clamp(0.55rem, 0.8vw, 0.72rem);

            --slide-padding: clamp(1.2rem, 3.5vw, 3.5rem);
            --content-gap: clamp(0.5rem, 1.5vw, 1.5rem);
            --element-gap: clamp(0.25rem, 0.8vw, 0.75rem);

            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* === RESET === */
        *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

        /* === VIEWPORT BASE (mandatory) === */
        html, body { height: 100%; overflow-x: hidden; }
        html { scroll-snap-type: y mandatory; scroll-behavior: smooth; }

        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }

        .feature-list, .bullet-list { gap: clamp(0.4rem, 1vh, 1rem); }
        .feature-list li, .bullet-list li { font-size: var(--body-size); line-height: 1.4; }

        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }

        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }

        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }

        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }

        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* === GLOBAL STYLES === */
        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            -webkit-font-smoothing: antialiased;
        }

        /* === BACKGROUND PATTERNS === */
        .slide::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(255,255,255,0.015) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,0.015) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
            z-index: 0;
        }

        .slide > * { position: relative; z-index: 1; }

        /* === ANIMATION === */
        .reveal {
            opacity: 0;
            transform: translateY(24px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }

        .reveal:nth-child(1) { transition-delay: 0.08s; }
        .reveal:nth-child(2) { transition-delay: 0.16s; }
        .reveal:nth-child(3) { transition-delay: 0.24s; }
        .reveal:nth-child(4) { transition-delay: 0.32s; }
        .reveal:nth-child(5) { transition-delay: 0.40s; }
        .reveal:nth-child(6) { transition-delay: 0.48s; }

        .reveal-scale {
            opacity: 0;
            transform: scale(0.95);
            transition: opacity 0.5s var(--ease-out-expo), transform 0.5s var(--ease-out-expo);
        }
        .slide.visible .reveal-scale { opacity: 1; transform: scale(1); }

        /* === PROGRESS BAR === */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent-teal), var(--accent-amber));
            z-index: 1000;
            transition: width 0.3s ease;
        }

        /* === NAV DOTS === */
        .nav-dots {
            position: fixed;
            right: clamp(0.75rem, 1.5vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: clamp(6px, 0.8vh, 10px);
            z-index: 100;
        }

        .nav-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--text-muted);
            border: none;
            cursor: pointer;
            transition: all 0.3s ease;
            padding: 0;
        }

        .nav-dot.active {
            background: var(--accent-teal);
            box-shadow: 0 0 8px var(--accent-teal);
            transform: scale(1.3);
        }

        /* === SLIDE LABEL === */
        .slide-label {
            position: absolute;
            top: var(--slide-padding);
            left: var(--slide-padding);
            font-family: var(--font-display);
            font-size: var(--tiny-size);
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.15em;
            color: var(--accent-teal);
            opacity: 0.7;
        }

        /* === TITLE SLIDE === */
        .title-slide {
            background: radial-gradient(ellipse at 30% 70%, rgba(45, 212, 191, 0.06) 0%, transparent 60%),
                        radial-gradient(ellipse at 80% 20%, rgba(245, 158, 11, 0.04) 0%, transparent 50%),
                        var(--bg-primary);
        }

        .title-slide .slide-content {
            align-items: flex-start;
            justify-content: center;
            max-width: min(85vw, 1100px);
        }

        .title-slide h1 {
            font-family: var(--font-display);
            font-size: var(--title-size);
            font-weight: 800;
            line-height: 1.15;
            letter-spacing: -0.02em;
            color: var(--text-primary);
        }

        .title-slide h1 .accent {
            background: linear-gradient(135deg, var(--accent-teal), var(--accent-blue));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .title-meta {
            display: flex;
            gap: clamp(1rem, 3vw, 2.5rem);
            margin-top: var(--content-gap);
            flex-wrap: wrap;
        }

        .meta-item {
            font-size: var(--small-size);
            color: var(--text-secondary);
            display: flex;
            align-items: center;
            gap: 0.4em;
        }

        .meta-item .dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: var(--accent-teal);
        }

        .title-divider {
            width: clamp(60px, 8vw, 120px);
            height: 2px;
            background: linear-gradient(90deg, var(--accent-teal), transparent);
            margin: var(--content-gap) 0;
        }

        .title-subtitle {
            font-family: var(--font-body);
            font-size: var(--body-size);
            color: var(--text-secondary);
            line-height: 1.6;
            max-width: 56ch;
        }

        /* === DATA TABLE SLIDE === */
        .data-table-wrap {
            width: 100%;
            overflow: hidden;
        }

        .data-table {
            width: 100%;
            border-collapse: collapse;
            font-size: var(--tiny-size);
            table-layout: fixed;
        }

        .data-table th {
            font-family: var(--font-display);
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.08em;
            color: var(--accent-teal);
            padding: clamp(3px, 0.4vh, 6px) clamp(4px, 0.6vw, 10px);
            border-bottom: 1px solid var(--border-accent);
            text-align: left;
            font-size: var(--tiny-size);
        }

        .data-table td {
            padding: clamp(2px, 0.35vh, 5px) clamp(4px, 0.6vw, 10px);
            border-bottom: 1px solid var(--border);
            color: var(--text-primary);
            font-variant-numeric: tabular-nums;
        }

        .data-table tr:hover td {
            background: rgba(45, 212, 191, 0.04);
        }

        .data-table .lang-name {
            font-weight: 600;
            font-family: var(--font-display);
        }

        .data-table .positive { color: var(--accent-green); }
        .data-table .negative { color: var(--accent-red); }
        .data-table .neutral { color: var(--text-muted); }

        .rank-change-up {
            display: inline-block;
            font-size: 0.75em;
            color: var(--accent-green);
            margin-left: 0.3em;
        }

        .rank-change-down {
            display: inline-block;
            font-size: 0.75em;
            color: var(--accent-red);
            margin-left: 0.3em;
        }

        .rank-same {
            display: inline-block;
            font-size: 0.75em;
            color: var(--text-muted);
            margin-left: 0.3em;
        }

        .data-table .highlight-row td {
            background: var(--accent-teal-dim);
        }

        /* === CONTENT SLIDE HEADINGS === */
        .content-slide h2 {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 800;
            line-height: 1.2;
            letter-spacing: -0.01em;
            margin-bottom: var(--content-gap);
        }

        .content-slide h3 {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 700;
            margin-bottom: var(--element-gap);
        }

        /* === MOVERS SLIDE === */
        .movers-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.75rem, 2vw, 2rem);
            width: 100%;
        }

        .movers-column {
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
        }

        .movers-column-title {
            font-family: var(--font-display);
            font-weight: 700;
            font-size: var(--small-size);
            text-transform: uppercase;
            letter-spacing: 0.12em;
            padding-bottom: clamp(4px, 0.5vh, 8px);
            margin-bottom: var(--element-gap);
        }

        .movers-column-title.gainers {
            color: var(--accent-green);
            border-bottom: 2px solid var(--accent-green);
        }

        .movers-column-title.losers {
            color: var(--accent-red);
            border-bottom: 2px solid var(--accent-red);
        }

        .mover-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.5rem, 1.2vh, 1rem) clamp(0.6rem, 1.2vw, 1.2rem);
            display: flex;
            align-items: center;
            justify-content: space-between;
            transition: transform 0.2s ease, border-color 0.2s ease;
        }

        .mover-card:hover {
            transform: translateX(4px);
        }

        .mover-card.gainer { border-left: 3px solid var(--accent-green); }
        .mover-card.loser { border-left: 3px solid var(--accent-red); }

        .mover-lang {
            font-family: var(--font-display);
            font-weight: 700;
            font-size: var(--body-size);
        }

        .mover-detail {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 2px;
        }

        .mover-change {
            font-family: var(--font-display);
            font-weight: 800;
            font-size: var(--h3-size);
            white-space: nowrap;
        }

        .mover-change.positive { color: var(--accent-green); }
        .mover-change.negative { color: var(--accent-red); }

        .mover-rank-shift {
            font-size: var(--tiny-size);
            color: var(--text-muted);
            text-align: right;
        }

        /* === HISTORICAL SLIDE === */
        .history-table {
            width: 100%;
            border-collapse: collapse;
            font-size: var(--tiny-size);
        }

        .history-table th {
            font-family: var(--font-display);
            font-weight: 700;
            color: var(--accent-teal);
            padding: clamp(3px, 0.4vh, 7px) clamp(4px, 0.5vw, 8px);
            border-bottom: 1px solid var(--border-accent);
            text-align: center;
            font-size: var(--tiny-size);
        }

        .history-table th:first-child { text-align: left; }

        .history-table td {
            padding: clamp(3px, 0.4vh, 6px) clamp(4px, 0.5vw, 8px);
            border-bottom: 1px solid var(--border);
            text-align: center;
            font-variant-numeric: tabular-nums;
        }

        .history-table td:first-child {
            text-align: left;
            font-weight: 600;
            font-family: var(--font-display);
        }

        .history-table .rank-1 {
            color: var(--accent-amber);
            font-weight: 700;
        }

        .history-table .rank-top3 {
            color: var(--accent-teal);
            font-weight: 600;
        }

        .history-table .unranked {
            color: var(--text-muted);
            font-style: italic;
        }

        .history-note {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: var(--element-gap);
            font-style: italic;
        }

        /* === HALL OF FAME === */
        .hof-grid {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            gap: clamp(0.4rem, 0.8vw, 0.8rem);
            width: 100%;
        }

        .hof-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.5rem, 1vh, 1rem) clamp(0.4rem, 0.8vw, 0.8rem);
            text-align: center;
            transition: transform 0.2s ease, border-color 0.2s ease;
        }

        .hof-card:hover {
            transform: translateY(-2px);
            border-color: var(--border-accent);
        }

        .hof-card.python { border-top: 3px solid var(--accent-amber); }
        .hof-card.csharp { border-top: 3px solid var(--accent-blue); }
        .hof-card.cpp { border-top: 3px solid var(--accent-teal); }
        .hof-card.c-lang { border-top: 3px solid var(--accent-green); }
        .hof-card.go-lang { border-top: 3px solid var(--accent-red); }

        .hof-year {
            font-family: var(--font-display);
            font-weight: 800;
            font-size: var(--h3-size);
            color: var(--text-muted);
        }

        .hof-winner {
            font-family: var(--font-display);
            font-weight: 700;
            font-size: var(--body-size);
            margin-top: clamp(2px, 0.3vh, 6px);
        }

        .hof-stat {
            display: flex;
            align-items: center;
            gap: var(--content-gap);
            margin-top: var(--content-gap);
            padding: clamp(0.5rem, 1vh, 1rem) clamp(0.75rem, 1.5vw, 1.5rem);
            background: var(--accent-amber-dim);
            border: 1px solid rgba(245, 158, 11, 0.2);
            border-radius: 8px;
        }

        .hof-stat-number {
            font-family: var(--font-display);
            font-weight: 900;
            font-size: var(--title-size);
            color: var(--accent-amber);
            line-height: 1;
        }

        .hof-stat-label {
            font-size: var(--body-size);
            color: var(--text-secondary);
            line-height: 1.4;
        }

        .hof-stat-label strong {
            color: var(--text-primary);
        }

        .hof-note {
            font-size: var(--tiny-size);
            color: var(--text-muted);
            margin-top: var(--element-gap);
            font-style: italic;
        }

        /* === TAKEAWAYS SLIDE === */
        .takeaway-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.5rem, 1.2vw, 1rem);
            width: 100%;
        }

        .takeaway-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.6rem, 1.2vh, 1.2rem) clamp(0.6rem, 1.2vw, 1.2rem);
        }

        .takeaway-card .tk-label {
            font-family: var(--font-display);
            font-weight: 700;
            font-size: var(--small-size);
            text-transform: uppercase;
            letter-spacing: 0.08em;
            margin-bottom: clamp(2px, 0.3vh, 6px);
        }

        .takeaway-card .tk-body {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .takeaway-card .tk-body strong {
            color: var(--text-primary);
        }

        .tk-label.teal { color: var(--accent-teal); }
        .tk-label.amber { color: var(--accent-amber); }
        .tk-label.green { color: var(--accent-green); }
        .tk-label.red { color: var(--accent-red); }
        .tk-label.blue { color: var(--accent-blue); }

        .takeaway-bottom {
            margin-top: var(--content-gap);
            padding: clamp(0.5rem, 1vh, 1rem) clamp(0.75rem, 1.5vw, 1.5rem);
            background: var(--accent-teal-dim);
            border: 1px solid var(--border-accent);
            border-radius: 8px;
            font-size: var(--body-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .takeaway-bottom strong {
            color: var(--accent-teal);
        }

        /* === BAR VIZ RATING === */
        .rating-bar-cell {
            display: flex;
            align-items: center;
            gap: clamp(3px, 0.4vw, 6px);
        }

        .rating-bar {
            height: clamp(5px, 0.6vh, 8px);
            border-radius: 4px;
            background: var(--accent-teal);
            opacity: 0.6;
            transition: width 0.8s var(--ease-out-expo);
        }

        /* col widths for the table */
        .col-rank { width: 6%; }
        .col-prev { width: 6%; }
        .col-lang { width: 22%; }
        .col-rating { width: 42%; }
        .col-yoy { width: 12%; }
        .col-arrow { width: 12%; }

        /* === FOOTER === */
        .slide-footer {
            position: absolute;
            bottom: clamp(8px, 1vh, 16px);
            left: var(--slide-padding);
            right: var(--slide-padding);
            display: flex;
            justify-content: space-between;
            font-size: var(--tiny-size);
            color: var(--text-muted);
        }
    </style>
</head>
<body>

<!-- Progress bar -->
<div class="progress-bar" id="progressBar"></div>

<!-- Navigation dots -->
<nav class="nav-dots" id="navDots" aria-label="Slide navigation"></nav>

<!-- ============================================ -->
<!-- SLIDE 1: TITLE                               -->
<!-- ============================================ -->
<section class="slide title-slide" id="slide-1">
    <div class="slide-content">
        <div class="reveal" style="margin-bottom: var(--element-gap);">
            <span style="font-family: var(--font-display); font-size: var(--small-size); font-weight: 600; text-transform: uppercase; letter-spacing: 0.15em; color: var(--accent-teal);">TIOBE Programming Community Index</span>
        </div>
        <h1 class="reveal">TIOBE Index March 2026:<br>How <span class="accent">20+ Search Engines</span> Rank the World's Programming Languages</h1>
        <div class="title-divider reveal"></div>
        <p class="title-subtitle reveal">Ratings calculated from skilled-engineer volume, training courses, and third-party vendors across Google, Bing, Wikipedia, Amazon, and 20+ additional sites. The index measures how much a language is discussed — not which is "best."</p>
        <div class="title-meta reveal">
            <span class="meta-item"><span class="dot"></span> March 2026</span>
            <span class="meta-item"><span class="dot"></span> Paul Jansen, TIOBE Software</span>
            <span class="meta-item"><span class="dot"></span> 50+ Languages Tracked</span>
        </div>
    </div>
    <div class="slide-footer">
        <span>TIOBE Index — March 2026 Report</span>
        <span>1 / 6</span>
    </div>
</section>

<!-- ============================================ -->
<!-- SLIDE 2: TOP 20 RANKINGS                     -->
<!-- ============================================ -->
<section class="slide content-slide" id="slide-2" style="background: radial-gradient(ellipse at 70% 80%, rgba(45,212,191,0.04) 0%, transparent 55%), var(--bg-primary);">
    <div class="slide-content" style="padding-top: clamp(1.8rem, 4vh, 3.5rem);">
